// 68 ekstra situationsspørgsmål. s = situation. Rigtigt svar står først i o.
window.QUESTIONS2 = [
// ===================== GRUNDBEGREBER =====================
{k:"grund", s:"Et vognmandsfirma kører møbler fra Vejle til Hamborg. En sofa kommer frem med en flænge. Chaufføren siger: 'Jeg har kørt forsigtigt, og jeg ved ikke, hvordan det skete.'",
 q:"Hjælper det fragtføreren, at chaufføren har kørt forsigtigt?",
 o:["Nej, CMR § 24 er objektivt ansvar, så forsigtighed alene fritager ikke","Ja, når chaufføren har været forsigtig, er der ingen skyld og intet ansvar","Ja, men kun hvis kunden ikke kan bevise noget andet","Nej, men kunden skal bevise, at chaufføren var uforsigtig"],
 f:"Turen går fra Danmark til Tyskland, så CMR gælder. CMR § 24 er objektivt ansvar. Fragtføreren hæfter for skader fra overtagelse til aflevering, også uden skyld. At chaufføren var forsigtig, er ikke nok. Fragtføreren kan kun slippe, hvis han beviser en konkret fritagelse i § 24 stk. 2 eller § 25, fx dårlig emballage fra afsender. Kunden skal ikke bevise skyld.",
 p:"CMR §§ 24-25."},
{k:"grund", s:"Et rederi sejler maskindele fra Aarhus til Oslo. En kasse bliver knust under sejladsen. Rederiet viser logbøger og vidner, der beviser, at lasten var surret efter alle regler, og at en usædvanlig storm kastede en anden containers indhold ind over kassen.",
 q:"Hvad er rederiets bedste chance efter søloven?",
 o:["At bevise, at hverken rederiet eller dets folk lavede fejl, så det slipper efter § 275","At sige, at søloven ikke gælder mellem Danmark og Norge","At henvise til, at kunden ikke har forsikring","At kræve, at kunden beviser rederiets skyld"],
 f:"Fart mellem Danmark og Norge er omfattet af søloven § 252. § 275 er culpa med omvendt bevisbyrde. Rederiet er ansvarligt, medmindre det beviser, at hverken det selv eller dets folk har lavet fejl. Her har rederiet beviser for korrekt surring og en usædvanlig storm. Karnov nævner domme, hvor rederier blev frifundet for hårdt vejr, men kun hvor de beviste, at de ikke havde lavet fejl. Er vejret normalt for årstiden, hjælper det ikke.",
 p:"SL §§ 252 og 275. Karnov-note 583."},
{k:"grund", s:"En kunde har fået ødelagt gods for 400.000 kr. Loftet er 80.000 kr. Kunden kan bevise, at chaufføren var lidt uopmærksom, men ikke mere.",
 q:"Kan kunden få hele tabet på 400.000 kr.?",
 o:["Nej, almindelig uagtsomhed giver ikke gennembrud, det kræver grov uagtsomhed eller forsæt","Ja, al uagtsomhed giver gennembrud","Ja, fordi tabet er stort","Nej, fordi kunden aldrig kan få mere end loftet"],
 f:"Gennembrud til fuld erstatning kræver forsæt eller grov uagtsomhed (CMR § 37, NSAB § 6 stk. 2, SL § 283). At chaufføren var lidt uopmærksom, er almindelig uagtsomhed. Så gælder loftet, og kunden får 80.000 kr. Kunden kunne have sikret sig med angiven værdi eller særlig interesse i fragtbrevet.",
 p:"CMR § 37, NSAB § 6 stk. 2, SL § 283."},
{k:"grund", s:"Et parti kaffe blev forsinket på en lastbil fra Holland. Imens steg kaffeprisen ikke, og køberen havde kaffe nok på lager. Han har ikke tabt noget, men vil alligevel have erstatning, fordi kaffen kom for sent.",
 q:"Kan køberen få erstatning?",
 o:["Nej, der skal være et økonomisk tab, og ved forsinkelse efter CMR skal tabet bevises","Ja, forsinkelse giver altid fragtbeløbet","Ja, 8,33 SDR pr. kg","Ja, fordi forsinkelse er objektivt ansvar"],
 f:"Første betingelse for erstatning er et økonomisk tab. CMR § 32 siger, at fragtføreren skal betale, hvis det godtgøres, at der er lidt skade som følge af forsinkelsen, dog højst fragtbeløbet. Karnov understreger, at den fulde bevisbyrde for tabet ligger på kunden. Uden tab er der ingen erstatning.",
 p:"CMR § 32. Karnov-note 106."},
{k:"grund", s:"En speditør kører et parti tøj for 2 mio. kr. Det vejer kun 1.000 kg. Kunden spørger, hvad han får, hvis alt bliver stjålet, og der ikke er grov uagtsomhed. (CMR, kurs 9,25)",
 q:"Hvad er loftet?",
 o:["Ca. 77.000 kr. (1.000 kg x 8,33 SDR x 9,25)","2 mio. kr.","Ca. 18.500 kr. (1.000 kg x 2 SDR x 9,25)","Ca. 240.000 kr. (1.000 kg x 26 SDR x 9,25)"],
 f:"CMR § 29 stk. 2: højst 8,33 SDR pr. kg. 1.000 x 8,33 = 8.330 SDR. Gange 9,25 = 77.052 kr. Det er under 4 procent af værdien. Derfor bør afsender af let og dyrt gods angive en højere værdi (§ 30) eller særlig interesse (§ 33) mod et tillæg. Dertil kommer fragt og told efter § 29 stk. 3.",
 p:"CMR §§ 29, 30 og 33."},
{k:"grund", s:"En transportør har betalt 500.000 kr. i erstatning til sin kunde for en skade, som hans undertransportør lavede. Transportøren vil ikke selv bære tabet.",
 q:"Hvad kan transportøren gøre?",
 o:["Kræve regres hos undertransportøren","Kræve pengene tilbage fra kunden","Intet, når han først har betalt","Sende regningen til staten"],
 f:"Transportøren hæfter over for kunden for sine undertransportører (SL § 285, CMR § 4, NSAB § 3B). Men bagefter kan han kræve pengene tilbage hos den, der faktisk lavede skaden. Det hedder regres. Søloven § 287 stk. 3 siger, at reglerne ikke hindrer aftaler om regres. CMR § 46 har regler om regres mellem fragtførere.",
 p:"SL § 287 stk. 3, CMR § 46."},

// ===================== NSAB =====================
{k:"nsab", s:"Danske Speditører-medlemmet NordFreight sælger en transport fra København til Stockholm til fast pris. NordFreight kører ikke selv, men hyrer vognmanden Svensson. Svensson ødelægger godset. NordFreight siger: 'Vi er bare mellemmand, ret kravet mod Svensson.'",
 q:"Har NordFreight ret?",
 o:["Nej, NordFreight er kontraherende speditør efter NSAB § 3B og hæfter for Svensson","Ja, en speditør er altid kun mellemmand","Ja, fordi Svensson lavede skaden","Nej, men kun fordi turen går til Sverige"],
 f:"NSAB § 3B siger, at speditøren er ansvarlig som kontraktspart for de opgaver, han har påtaget sig, og for medkontrahenter, han har hyret. Kun hvis speditøren tydeligt har sagt til kunden, at han kun er formidler, og ikke handler i eget navn og for egen regning, gælder § 3C. NordFreight solgte transporten til fast pris i eget navn. Derfor hæfter NordFreight, og kan så tage regres hos Svensson.",
 p:"NSAB §§ 3B og 3C."},
{k:"nsab", s:"En speditør skriver i sin aftale: 'Vi formidler kun transporten. Aftalen indgås i jeres navn med vognmanden. Vi handler ikke for egen regning.' Vognmanden, som speditøren valgte, ødelægger godset. Vognmanden var kendt og godkendt.",
 q:"Hvad hæfter speditøren for?",
 o:["Kun for manglende omhu, fx ved valget af vognmanden, efter NSAB § 22","For hele skaden som transportør","For intet, heller ikke egne fejl","For dobbelt erstatning"],
 f:"Her er formidlerrollen aftalt tydeligt (NSAB § 3C). Så gælder § 22: speditøren er ansvarlig, hvis han ikke har vist tilbørlig omhu. Han er ikke ansvarlig for tredjemands fejl under transporten. Man ser på, hvad han vidste om vognmanden. Vognmanden var kendt og godkendt, så speditøren slipper formentlig. Kunden må rette kravet mod vognmanden.",
 p:"NSAB §§ 3C og 22."},
{k:"nsab", s:"En NSAB-speditør kører gods fra Fredericia til Rotterdam med lastbil og videre med skib til England. Kassen kommer frem knust. Speditøren kan ikke finde ud af, om det skete på lastbilen, på havnen eller på skibet.",
 q:"Hvilke regler afgør sagen?",
 o:["NSAB §§ 15-21, fordi man ikke kan bevise, på hvilken transportform skaden skete","CMR, fordi lastbilen kørte først","Søloven, fordi skibet sejlede sidst","Den lov, der giver kunden mindst"],
 f:"Netværksreglen i NSAB § 2 kræver, at en bestemt transportform er aftalt, eller at det kan bevises, hvor skaden skete. Ingen af delene er opfyldt. Derfor bliver man i NSAB. Ansvaret efter § 15 er objektivt med fritagelser i § 16. Loftet er 8,33 SDR pr. kg (§ 21). NSAB § 6 stk. 3 siger også, at det ukendte forløb ikke i sig selv er grov uagtsomhed.",
 p:"NSAB §§ 2, 6 stk. 3, 15-21."},
{k:"nsab", s:"En kunde har aftalt med en NSAB-speditør, at en sending skal sejles fra Esbjerg til Harwich. Speditøren læsser i stedet godset på en lastbil, der kører over land. Godset bliver skadet på lastbilen.",
 q:"Hvorfor er det vigtigt, at transportformen var aftalt?",
 o:["Fordi NSAB § 2 også bruger loven for den aftalte transportform","Fordi aftalen så er ugyldig","Fordi kunden så mister sit krav","Det er ligegyldigt"],
 f:"NSAB § 2 har to ben: 1) hvis særlig aftale er truffet om en bestemt transportmåde, eller 2) hvis det kan bevises, hvor skaden skete. Er sejlads aftalt, peger det første ben på søloven. Men her ved man også, at skaden skete på lastbilen. Til eksamen skal du forklare begge ben og diskutere, hvilken lov der giver det rigtige resultat. Speditøren har desuden brudt aftalen ved at skifte transportform.",
 p:"NSAB § 2."},
{k:"nsab", s:"En speditør har lovet skriftligt: 'Levering senest fredag kl. 12, tidsgaranteret.' Lastbilen kommer mandag. Kunden har ikke dokumenteret noget tab.",
 q:"Hvad får kunden efter NSAB?",
 o:["Fragten krediteret, fordi der var tidsløfte, medmindre speditøren beviser, at forsinkelsen var uden for hans kontrol","Intet, fordi kunden ikke har bevist tab","8,33 SDR pr. kg","Godsets fulde værdi"],
 f:"NSAB § 7 stk. 2 handler om tidsløfte, fx skriftlig tidsgaranteret transport. § 19 litra B siger, at ved overskridelse skal speditøren kreditere den aftalte fragt. Kunden anses for at have tabt mindst fragtbeløbet, medmindre det bevises, at tabet er mindre. Speditøren slipper, hvis forsinkelsen skyldes forhold uden for hans kontrol. Ved vejtransport i Europa hæfter han også for sine medkontrahenters forhold.",
 p:"NSAB §§ 7 stk. 2 og 19 B."},
{k:"nsab", s:"En NSAB-speditør skal køre gods fra Aalborg til Odense. Der er intet aftalt om tidspunkt. Speditøren har i sit tilbud skrevet 'normalt 1 dags levering'. Godset kommer efter 4 dage, og kunden har haft ekstra udgifter til en lejet maskine.",
 q:"Hvad kan kunden få efter NSAB § 19 A?",
 o:["Direkte og rimelige omkostninger, som kunne forudses, højst fragten","Godsets fulde værdi","Intet, fordi der ikke var tidsløfte","Tabt fortjeneste uden loft"],
 f:"Uden tidsløfte gælder NSAB § 7 stk. 1: godset skal fremme inden rimelig tid, og man ser på det, speditøren har oplyst i tilbuddet. Her var det 1 dag, så 4 dage er for sent. § 19 A siger, at der betales for direkte og rimelige omkostninger, som speditøren kunne forudse som en sandsynlig følge af forsinkelsen, dog højst den aftalte fragt. Udgiften til en lejet maskine kan være en sådan omkostning.",
 p:"NSAB §§ 7 stk. 1 og 19 A."},
{k:"nsab", s:"Kunden pakkede selv glas i tynde papkasser uden polstring. En NSAB-speditør kører kasserne. Mange glas går i stykker, selv om kørslen var normal.",
 q:"Kan speditøren slippe for ansvar?",
 o:["Ja, efter NSAB § 16 litra d om manglende eller mangelfuld emballage","Nej, NSAB har ingen fritagelser","Nej, speditøren hæfter altid for glas","Ja, men kun hvis glasset var billigt"],
 f:"NSAB § 15 er objektivt ansvar, men § 16 har fritagelser. Litra d nævner manglende eller mangelfuld emballage. Litra c nævner også godsets egen letskadelige beskaffenhed som brækage. Speditøren skal bevise, at skaden skyldes emballagen. Ordregiveren kan desuden efter § 26 blive ansvarlig over for speditøren, hvis den dårlige emballage skader andet gods.",
 p:"NSAB §§ 16 og 26."},
{k:"nsab", s:"En kunde har opbevaret 100 paller på en speditørs lager i et år. Kunden opgav ikke varernes værdi. Der bryder brand ud, og alle paller brænder.",
 q:"Hvad siger NSAB § 25 om forsikring?",
 o:["Speditøren skal forsikre godset for brand, vand og indbrud, og han må selv anslå værdien, hvis kunden ikke har oplyst den","Kunden skal altid selv forsikre","Lager er ikke dækket af NSAB","Speditøren betaler 8,33 SDR pr. kg uden forsikring"],
 f:"NSAB § 25 A siger, at speditøren i eget navn og for kundens regning skal tegne forsikring for brand, vand og indbrud baseret på fakturaværdien plus 10 procent. Har kunden ikke oplyst værdien, må speditøren anslå den, og kunden bærer risikoen for anslaget. For skader uden for forsikringen hæfter speditøren for fejl efter §§ 17-18 og 21, højst 500.000 SDR pr. hændelse.",
 p:"NSAB § 25."},
{k:"nsab", s:"En kunde opdager 10 dage efter leveringen, at nogle varer i en uåbnet kasse er ødelagt. Han reklamerer til speditøren (NSAB) samme dag, som han opdager det.",
 q:"Hvad er problemet?",
 o:["Skjult skade skal reklameres inden 7 kalenderdage, så kunden skal nu bevise, at skaden skete hos speditøren","Der er intet problem, han reklamerede samme dag","Kravet er forældet","Han skulle have reklameret inden 1 år"],
 f:"NSAB § 27 siger, at ikke-synlig skade skal reklameres senest 7 kalenderdage fra leveringen. Kunden reklamerede efter 10 dage. Følgen er efter § 27, at det påhviler kunden at bevise, at skaden opstod, mens godset var hos speditøren. Kunden mister altså ikke automatisk kravet, men får en svær bevisbyrde.",
 p:"NSAB § 27."},
{k:"nsab", s:"En speditør skylder ikke kunden noget, men kunden har ikke betalt speditørens sidste 3 fakturaer. Nu har speditøren en ny sending fra kunden på sit lager.",
 q:"Hvad må speditøren efter NSAB?",
 o:["Holde godset tilbage og i sidste ende sælge det for at dække sine krav","Intet, han skal udlevere godset","Kun sende en rykker","Smide godset ud"],
 f:"NSAB § 14 giver speditøren tilbageholdsret og panteret i gods, han har kontrol over, både for omkostninger på godset og for alle andre krav mod kunden fra hans opgaver. Betales der ikke, må han på betryggende måde sælge så meget af godset, som dækker kravene. Han skal så vidt muligt varsle kunden i god tid.",
 p:"NSAB § 14."},

// ===================== PARTER =====================
{k:"parter", s:"En dansk køber køber maskiner FOB Hamborg fra en tysk sælger. Køberen booker selv skibet hos et rederi. Sælgeren kører maskinerne ned til kajen og afleverer dem til rederiet.",
 q:"Hvem er afsender, og hvem er aflaster efter søloven?",
 o:["Køber er afsender (har aftalen), sælger er aflaster (afleverer godset)","Sælger er afsender, køber er aflaster","Begge er afsendere","Rederiet er aflaster"],
 f:"Søloven § 251 nr. 3: afsender er den, der laver aftale med transportøren. Det gør køber, fordi køber har bestilt skibet ved FOB. § 251 nr. 4: aflaster er den, der leverer godset til transport. Det gør sælgeren. Karnov nævner netop FOB-køb som eksemplet på, at afsender og aflaster er to forskellige.",
 p:"SL § 251 nr. 3 og 4. Karnov-note 508."},
{k:"parter", s:"Speditøren Blue Water har lavet aftale med Furs & Feathers. Blue Water bruger Air Greenland til flyet, DHL til lastbilen og DSV's terminal i Hamburg. Skindene bliver ødelagt.",
 q:"Hvem skal Furs & Feathers rette kravet mod?",
 o:["Blue Water, fordi det er den kontraherende speditør","Air Greenland","DHL","DSV"],
 f:"Furs & Feathers har kun aftale med Blue Water. Blue Water er kontraherende speditør og hæfter for sine medkontrahenter efter NSAB § 3B. Air Greenland, DHL og DSV er undertransportører eller hjælpere. CJ skrev: 'Ansvarlig part er stadig BWS, selvom erstatningssagen skal afgøres ifølge luftfartslovens kapitel 9.' Blue Water kan bagefter tage regres.",
 p:"NSAB § 3B. CJ lektion 6."},
{k:"parter", s:"En vognmand har overtaget en sending fra en anden vognmand undervejs på samme CMR-fragtbrev. Godset bliver skadet. Kunden ved ikke, hvem af de tre vognmænd der lavede skaden.",
 q:"Hvem kan kunden sagsøge efter CMR § 45?",
 o:["Den første, den sidste, eller den, der kørte, da skaden skete","Kun den, der lavede skaden","Kun den første","Ingen, når det er uklart"],
 f:"CMR § 43 siger, at flere fragtførere efter hinanden på samme fragtbrev alle bliver ansvarlige for hele transporten. § 45 siger, at søgsmål kan anlægges mod den første, den sidste, eller den fragtfører, der udførte den del, hvor skaden skete. Det hjælper kunden, når han ikke ved, hvor skaden skete. Fragtførerne fordeler bagefter erstatningen indbyrdes efter § 46.",
 p:"CMR §§ 43-46."},
{k:"parter", s:"En undertransportør på et skib sejler godset fra Bremerhaven til Barcelona. Godset bliver skadet. Kunden har ingen aftale med undertransportøren, men vil sagsøge ham direkte, fordi den kontraherende transportør er gået konkurs.",
 q:"Kan kunden det efter søloven?",
 o:["Ja, § 286 siger, at undertransportøren hæfter for sin del efter samme regler","Nej, kunden har ingen aftale med ham","Kun hvis undertransportøren er dansk","Kun efter CMR"],
 f:"Søloven § 286 siger, at en undertransportør, der udfører transporten med skib, er ansvarlig for den del, han udfører, efter de samme regler som transportøren. § 287 siger, at de hæfter solidarisk. Kunden kan altså gå direkte til undertransportøren, men loftet i § 280 gælder også for ham.",
 p:"SL §§ 286-287."},
{k:"parter", s:"En afsender giver forkert vægt i fragtbrevet: der står 5 tons, men godset vejer 8 tons. Fragtføreren får en bøde ved vejningen, og lastbilen bliver skadet af overvægten.",
 q:"Hvem hæfter for fragtførerens tab efter CMR?",
 o:["Afsenderen, efter CMR § 9 om urigtige oplysninger til fragtbrevet","Fragtføreren selv","Modtageren","Ingen"],
 f:"CMR § 9 siger, at afsenderen er ansvarlig for omkostninger og skade, som fragtføreren lider, fordi oplysninger til fragtbrevet, fx bruttovægt, er urigtige eller ufuldstændige. Karnov siger, at ansvaret er objektivt og ubegrænset. Dommen U 2000 1736 H handlede netop om forkert opgivet vægt og en toldbøde.",
 p:"CMR § 9. Karnov-note 34."},

// ===================== TRANSPORTFORMER =====================
{k:"former", s:"En lastbil kører gods fra København til Rønne på Bornholm. Den kører gennem Sverige og tager færgen fra Ystad. Godset bliver skadet i Sverige.",
 q:"Gælder CMR?",
 o:["Nej, aftalen går mellem to steder i Danmark, selv om lastbilen kører gennem Sverige","Ja, fordi lastbilen var i Sverige","Ja, fordi skaden skete i udlandet","Kun på færgen"],
 f:"Karnov-noten til CMR § 1 siger, at CMR ikke gælder for transporter, der efter aftalen skal ske mellem steder i Danmark, selv om godset passerer fremmed territorium, og selv om skaden sker i udlandet. Karnov nævner netop transporter til og fra Bornholm via Skåne. Så bruger man aftalen, fx NSAB.",
 p:"CMR § 1. Karnov-note 5."},
{k:"former", s:"Et flyttefirma kører en families møbler fra Aarhus til Berlin. Et skab bliver ødelagt.",
 q:"Gælder CMR for flytningen?",
 o:["Nej, CMR § 1 stk. 2 undtager flyttegods","Ja, alle vejtransporter mellem lande","Kun hvis møblerne er nye","Kun hvis der er fragtbrev"],
 f:"CMR § 1 stk. 2 siger, at loven ikke gælder for befordringer omfattet af internationale postkonventioner, begravelsestransporter og befordring af flyttegods. Karnov siger, at begrebet flyttegods skal forstås snævert. En almindelig familieflytning er omfattet af undtagelsen.",
 p:"CMR § 1 stk. 2."},
{k:"former", s:"En container køres med lastbil fra Struer til Esbjerg. Her løftes containeren af lastbilen og sættes på en skibstrailer, som sejles til Harwich. Godset bliver skadet til søs.",
 q:"Gælder CMR's piggyback-regel (§ 3) for sejladsen?",
 o:["Nej, fordi containeren blev løftet af lastbilen og ikke blev på køretøjet","Ja, alle kombinerede transporter","Ja, fordi turen startede på vej","Kun hvis det er en dansk lastbil"],
 f:"CMR § 3 kræver, at godset bliver på køretøjet under sejladsen. Karnov nævner U 1989 593 H: en container fra Struer blev i Esbjerg løftet af lastbilen og sat på en skibstrailer. Så var transporten ikke omfattet af CMR. Til søs gælder så søloven. Kørte hele lastbilen om bord, ville CMR gælde.",
 p:"CMR § 3. Karnov-note 9."},
{k:"former", s:"En tog-transport fra Danmark til Italien med gods. En vogn afspores i Østrig, og godset bliver ødelagt.",
 q:"Hvilke regler gælder?",
 o:["CIM (COTIF), reglerne for international jernbanetransport","CMR","Søloven","Luftfartsloven"],
 f:"CIM art. 1 siger, at reglerne gælder for enhver aftale om international jernbanetransport af gods mod betaling, når afsendelses- og bestemmelsesstedet ligger i to forskellige medlemsstater. Danmark og Italien er begge med. Loftet er 17 SDR pr. kg (art. 30). Jernbanen slipper kun, hvis den beviser en fritagelse (art. 23 og 25).",
 p:"CIM art. 1, 23, 25 og 30."},
{k:"former", s:"En speditør sender gods fra Billund til New York med fly. Speditøren hyrer et flyselskab. Godset bliver ødelagt under flyvningen.",
 q:"Hvilke regler afgør flyselskabets ansvar?",
 o:["Luftfartsloven kapitel 9, som bygger på Montreal-konventionen","CMR","Søloven","Købeloven"],
 f:"Luftfartsloven § 90 siger, at kapitel 9 gælder for befordring af gods med luftfartøj mod betaling, som er omfattet af Montreal-konventionen. USA og Danmark er med. Ansvaret for skade er objektivt (§ 108), og loftet er 26 SDR pr. kg (§ 111 stk. 5). Er speditøren NSAB-medlem, sender NSAB § 2 sagen til luftfartsloven.",
 p:"LFL §§ 90, 108 og 111. NSAB § 2."},

// ===================== SØLOVEN =====================
{k:"so", s:"Et rederi har skrevet i sit konnossement: 'Rederiet hæfter kun, mens godset hænger i skibets kran og er om bord (tackle to tackle).' Godset bliver skadet på rederiets terminal, før det blev lastet.",
 q:"Gælder klausulen?",
 o:["Nej, varetægtsperioden i § 274 omfatter også havnen, og § 254 gør afvigende klausuler ugyldige","Ja, kunden har accepteret konnossementet","Ja, men kun i udlandet","Nej, men kun hvis kunden er forbruger"],
 f:"Søloven § 274 siger, at transportøren hæfter, mens han har godset i lastehavnen, under transporten og i lossehavnen. § 254 siger, at aftaler, der afviger fra kapitel 13 til skade for kunden, er ugyldige. Karnov siger direkte, at 'tackle to tackle'-klausuler er uden effekt, og nævner U 2011.271 H. Rederiet hæfter efter § 275.",
 p:"SL §§ 254 og 274. Karnov-note 518."},
{k:"so", s:"En container med fisk sejles fra Grønland til Aalborg. Under sejladsen bryder der brand ud i maskinrummet. Branden skyldtes en fejl hos en maskinist. Fisken bliver ødelagt af røg.",
 q:"Hæfter rederiet?",
 o:["Nej, brand fritager efter § 276, medmindre den skyldes transportøren selv","Ja, fordi en ansat lavede fejlen","Ja, brand er aldrig en fritagelse","Nej, fordi fisk er letfordærvelig"],
 f:"Søloven § 276 stk. 1 nr. 2 siger, at transportøren ikke er ansvarlig for brand, medmindre den er forårsaget ved fejl eller forsømmelse af transportøren selv. En maskinists fejl er ikke 'transportøren selv'. Karnov nævner, at også røg- og vandskader fra slukningen er omfattet. Fritagelsen er en særlig søretlig regel, fordi sørejsen er en fælles fare for skib og last.",
 p:"SL § 276 stk. 1 nr. 2. Karnov-note 588."},
{k:"so", s:"Et skib går på grund, fordi styrmanden læste søkortet forkert. Lasten af stål bliver beskadiget af havvand.",
 q:"Hæfter rederiet over for lastens ejer?",
 o:["Nej, fejl i navigeringen er en nautisk fejl, der fritager efter § 276","Ja, styrmanden er ansat af rederiet","Ja, fordi stål ikke er letfordærveligt","Nej, fordi stål ikke kan skades"],
 f:"Søloven § 276 stk. 1 nr. 1 siger, at transportøren ikke er ansvarlig for fejl i navigeringen eller behandlingen af skibet udvist af skibsfører, mandskab eller lods. At læse søkortet forkert er en navigationsfejl. Det er en særlig fritagelse i søretten, som hverken CMR eller luftfart har. Men var skibet usødygtigt fra starten, hæfter rederiet efter stk. 2.",
 p:"SL § 276."},
{k:"so", s:"Et skib sejler fra Aarhus med en defekt ventil i lastrummet, som rederiet kunne have opdaget ved et normalt eftersyn. Undervejs løber vand ind og ødelægger lasten. Rederiet siger: 'Det er en nautisk fejl.'",
 q:"Hvem har ret?",
 o:["Kunden, fordi usødygtighed ved rejsens begyndelse ikke er fritaget, når rederiet ikke viste tilbørlig omhu","Rederiet, fordi det skete under sejladsen","Rederiet, fordi vand er en naturkraft","Ingen af dem"],
 f:"§ 276 stk. 2 siger, at transportøren er ansvarlig for tab ved usødygtighed, hvis han ikke med tilbørlig omhu har sørget for, at skibet var sødygtigt ved rejsens begyndelse. Bevisbyrden for omhu ligger på transportøren. En ventil, der kunne have været opdaget ved normalt eftersyn, er manglende omhu. Karnov nævner flere domme om utætte rør og ventiler, hvor rederiet blev ansvarligt.",
 p:"SL §§ 262 stk. 2 og 276 stk. 2. Karnov-note 589."},
{k:"so", s:"En rederi-kaptajn ændrer kurs for at redde besætningen fra en synkende fiskerbåd. Skibet kommer 2 dage for sent, og frugten om bord bliver overmoden.",
 q:"Hæfter rederiet for frugten?",
 o:["Nej, § 275 stk. 2 fritager for tab ved redning af personer","Ja, rederiet skulle have sejlet videre","Ja, forsinkelse er altid ansvar","Kun for halvdelen"],
 f:"Søloven § 275 stk. 2 siger, at transportøren ikke er ansvarlig for tab, der skyldes foranstaltninger for at redde personer eller rimelige foranstaltninger for at bjærge skib eller anden ejendom til søs. At redde mennesker fra en synkende båd er netop det. Reglen gælder også forsinkelse, fordi § 278 henviser til §§ 275-277.",
 p:"SL §§ 275 stk. 2 og 278."},
{k:"so", s:"Et parti på 200 kasser à 50 kg står i konnossementet som '200 cartons'. Hele partiet går tabt til søs. (kurs 9,25)",
 q:"Hvad er sølovens loft?",
 o:["Ca. 1.234.000 kr. (200 x 667 SDR), fordi det er højere end vægten","Ca. 185.000 kr. (10.000 kg x 2 SDR)","Ca. 771.000 kr. (10.000 kg x 8,33 SDR)","Ca. 2,4 mio. kr. (10.000 kg x 26 SDR)"],
 f:"Regn begge efter § 280. Vægt: 200 x 50 = 10.000 kg x 2 SDR = 20.000 SDR = 185.000 kr. Kolli: 200 x 667 = 133.400 SDR = 1.233.950 kr. Det højeste gælder. Fordi kasserne står i konnossementet, tæller hver kasse som et kollo (§ 281). 8,33 SDR er CMR og NSAB, og 26 SDR er luftfart.",
 p:"SL §§ 280-281."},
{k:"so", s:"En container med 30 paller syltetøj bliver 25 dage forsinket til søs. Fragten for containeren var 20.000 kr. Fragten for hele aftalen (2 containere) var 40.000 kr. Kundens tab ved forsinkelsen er 70.000 kr.",
 q:"Hvad er sølovens loft for forsinkelsen?",
 o:["40.000 kr. (2,5 x 20.000 = 50.000, men højst hele fragten på 40.000)","50.000 kr.","70.000 kr.","20.000 kr."],
 f:"Søloven § 280 stk. 2 siger, at ansvaret for forsinkelse er begrænset til 2,5 gange fragten for det forsinkede gods, dog højst den samlede fragt efter aftalen. 2,5 x 20.000 = 50.000 kr. Men den samlede fragt er kun 40.000 kr. Derfor er loftet 40.000 kr. 25 dage er under 60 dage, så det kan ikke behandles som totaltab efter § 278 stk. 3.",
 p:"SL § 280 stk. 2 og § 278 stk. 3."},
{k:"so", s:"Et B/L siger, at 500 sække var 'in apparent good order'. En bank køber konnossementet i god tro og betaler sælgeren. Ved udleveringen er 100 sække våde. Rederiet kan bevise, at sækkene var våde, allerede da de blev lastet.",
 q:"Kan rederiet bruge beviset over for banken?",
 o:["Nej, over for en tredjemand i god tro, der har indløst B/L, er modbevis ikke tilladt","Ja, sandheden går altid forud","Ja, hvis rederiet har fotos","Kun hvis banken er udenlandsk"],
 f:"Søloven § 299 stk. 3 siger, at har tredjemand i god tro indløst konnossementet i tillid til oplysningerne, er modbevis ikke tilladt. Rederiet burde have taget forbehold om de våde sække (§ 298). Efter § 300 kan rederiet desuden blive ansvarligt uden loft, hvis det burde have indset, at B/L var vildledende.",
 p:"SL §§ 298-300."},
{k:"so", s:"Et rederi tager imod en container, som afsender selv har pakket (FCL). Rederiet har ikke åbnet den. Ved udleveringen er indholdet knust, fordi godset ikke var surret inde i containeren.",
 q:"Hvem bærer tabet?",
 o:["Formentlig afsenderen, fordi han pakkede containeren, og rederiet ikke skal undersøge den indvendigt uden grund","Rederiet altid","Modtageren","De deler altid 50-50"],
 f:"Søloven § 256 siger, at transportøren ikke skal undersøge en container indvendigt, medmindre der er grund til at tro, at den er dårligt pakket. Karnov siger ved § 255, at når afskiber selv har pakket containeren (FCL), skal han sikre, at godset er surret, så det ikke flytter sig. Rederiet kan så bevise efter § 275, at skaden ikke skyldes dets fejl.",
 p:"SL §§ 255, 256 og 275. Karnov-note 527."},
{k:"so", s:"En kunde opdager ved udleveringen fra skibet, at 5 kasser er knust. Han tager imod godset uden at sige noget og skriver først til rederiet 2 uger senere.",
 q:"Hvad er følgen efter søloven § 288?",
 o:["Godset formodes udleveret i den stand, B/L beskriver, men kunden kan stadig føre modbevis","Kunden har mistet sit krav helt","Ingen følger","Rederiet skal betale dobbelt"],
 f:"§ 288 stk. 1 siger, at er godset udleveret uden skriftlig meddelelse om synlig skade, anses det for udleveret i den stand, transportdokumentet beskriver, hvis ikke modbevis føres. Karnov siger, at det er en formodningsregel, ikke en regel, hvor kravet tabes. Kunden har nu en svær bevisbyrde. Ved forsinkelse ville han derimod miste kravet efter stk. 3.",
 p:"SL § 288. Karnov-note 613."},
{k:"so", s:"Et konnossement er stilet 'to order'. Sælgeren overdrager det først til bank A og bagefter, ved en fejl, et andet eksemplar til bank B. Begge er i god tro.",
 q:"Hvem har ret til godset efter søloven?",
 o:["Den, der i god tro fik sit eksemplar først","Den, der kommer først til havnen","Begge deler godset","Sælgeren"],
 f:"Søloven § 306 siger, at overdrager den, der fremstår som rette indehaver, forskellige eksemplarer af et ordre- eller ihændehaverkonnossement til flere personer, får den erhverver, der i god tro fik sit eksemplar først, ret til godset. Det viser, at konnossementet er et værdipapir, der repræsenterer godset.",
 p:"SL §§ 292, 302 og 306."},
{k:"so", s:"Et rederi skal sejle en usædvanlig last: levende laks i tanke. Det vil aftale med kunden, at rederiet ikke hæfter for laks, der dør.",
 q:"Kan de aftale det efter søloven?",
 o:["Kun hvis godsets usædvanlige art gør det rimeligt efter § 254 stk. 4, og Karnov viser, at det ikke var nok for laks","Ja, alt kan aftales","Nej, aldrig","Ja, fordi laks er levende dyr"],
 f:"§ 254 stk. 4 siger, at er det på grund af godsets usædvanlige beskaffenhed rimeligt, kan man aftale at indskrænke transportørens forpligtelser. Karnov nævner NDS 2001 164, hvor særegne forhold ved transport af levende laks og manglende forsikring ikke var nok til at begrunde en fravigelse.",
 p:"SL § 254 stk. 4. Karnov-note 521."},

// ===================== CMR =====================
{k:"cmr", s:"En kølebil kører kød fra Danmark til Italien. Kølemaskinen går i stå i 10 timer, fordi den ikke var serviceret. Kødet bliver fordærvet. Fragtføreren siger, at kød naturligt kan fordærves (§ 25 litra d).",
 q:"Kan fragtføreren bruge § 25 litra d?",
 o:["Nej, ved kølebiler skal han bevise, at han valgte, vedligeholdt og brugte køleudstyret rigtigt (§ 25 stk. 3)","Ja, kød er altid letfordærveligt","Ja, hvis kødet var dyrt","Nej, fordi kød ikke er gods"],
 f:"CMR § 25 stk. 3 siger, at ved køretøjer med særligt udstyr mod varme og kulde kan fragtføreren kun bruge litra d, hvis han beviser, at han tog alle forholdsregler med valg, vedligeholdelse og brug af udstyret og fulgte anvisningerne. En maskine, der ikke var serviceret, opfylder ikke det. Og § 24 stk. 3 siger, at mangler ved køretøjet aldrig fritager. Karnov nævner U 1969 582 S om et køleanlæg, der svigtede.",
 p:"CMR §§ 24 stk. 3 og 25 stk. 3. Karnov-note 92."},
{k:"cmr", s:"En fragtfører kører en levende hest fra Danmark til Tyskland. Afsender har givet skriftlige instrukser om vand hver 4. time. Chaufføren glemmer at give vand, og hesten bliver syg.",
 q:"Kan fragtføreren bruge fritagelsen for levende dyr (§ 25 litra f)?",
 o:["Nej, han skal bevise, at han tog alle normale forholdsregler og fulgte anvisningerne (§ 25 stk. 4)","Ja, dyr er altid fritaget","Ja, hvis hesten var gammel","Kun hvis det var varmt"],
 f:"CMR § 25 stk. 4 siger, at fragtføreren kun kan bruge litra f om levende dyr, hvis han beviser, at han tog alle forholdsregler, der normalt påhvilede ham, og fulgte de særlige anvisninger. Chaufføren fulgte ikke instruksen om vand. Derfor kan fritagelsen ikke bruges, og fragtføreren hæfter efter § 24.",
 p:"CMR § 25 stk. 1 litra f og stk. 4."},
{k:"cmr", s:"Afsender har sat forkerte adresser og numre på 20 kolli. Fragtføreren afleverer dem til den forkerte modtager, og de bliver væk.",
 q:"Hvad kan fragtføreren påberåbe sig?",
 o:["CMR § 25 litra e om ufuldstændige eller urigtige mærker eller numre","Ingen fritagelse","§ 24 stk. 3 om køretøjet","Nautisk fejl"],
 f:"CMR § 25 stk. 1 litra e fritager for bortkomst eller skade, der skyldes de særlige farer ved ufuldstændige eller urigtige mærker eller numre på kollierne. Efter § 25 stk. 2 skal fragtføreren kun vise, at tabet kan skyldes mærkningen. Karnov tilføjer, at fragtføreren kan have pligt til at gøre afsender opmærksom på fejl i mærkningen, hvis han ser dem.",
 p:"CMR § 25 stk. 1 litra e. Karnov-note 89."},
{k:"cmr", s:"En chauffør henter 20 paller. Han kan ikke tælle dem ordentligt, fordi de står bag andre paller. Han skriver ikke noget på fragtbrevet. Ved levering mangler 3 paller.",
 q:"Hvad skulle chaufføren have gjort efter CMR § 10?",
 o:["Taget forbehold i fragtbrevet med begrundelse, når han ikke kunne tælle kollierne med rimelige midler","Intet, det er afsenders problem","Ringet til politiet","Nægtet at køre"],
 f:"CMR § 10 stk. 1 siger, at fragtføreren skal undersøge, om antallet af kolli er rigtigt. Kan det ikke gøres med rimelige midler, skal han tage forbehold og skrive grunden i fragtbrevet. Uden forbehold formodes antallet at have været rigtigt (§ 11 stk. 2). Så hæfter fragtføreren for de 3 manglende paller efter § 24.",
 p:"CMR §§ 10-11 og 24."},
{k:"cmr", s:"Afsenderens folk læssede og stuvede godset. Under kørslen forskyder læsset sig, og noget af godset vælter. Chaufføren kunne ikke se nogen fejl ved læsningen, da han kørte.",
 q:"Kan fragtføreren slippe?",
 o:["Ja, formentlig efter § 25 litra c om afsenders læsning og stuvning","Nej, fragtføreren hæfter altid for læsset","Nej, chaufføren skulle have læsset om","Kun hvis det regnede"],
 f:"CMR § 25 stk. 1 litra c fritager for skader, der skyldes læsning, stuvning eller aflæsning udført af afsender eller modtager. Karnov siger, at det omfatter skader ved forskydning af læsset og væltning. Har chaufføren ikke haft grund til at se en fejl, frifindes fragtføreren, fx U 1980 96 H. Kunne han derimod se, at læsset var farligt, skulle han have grebet ind.",
 p:"CMR § 25 stk. 1 litra c. Karnov-note 87."},
{k:"cmr", s:"En fragtfører kører 2.000 kg gods. Afsender har i fragtbrevet angivet en værdi på 100.000 SDR og betalt et tillæg. Hele sendingen bliver stjålet, og den faktiske værdi var 80.000 SDR.",
 q:"Hvad får kunden?",
 o:["80.000 SDR, fordi den angivne værdi hæver loftet, men kunden skal stadig bevise den faktiske værdi","100.000 SDR uanset hvad","16.660 SDR (2.000 kg x 8,33)","Intet"],
 f:"CMR § 30 siger, at med angiven værdi træder den angivne værdi i stedet for loftet på 8,33 SDR pr. kg. Men Karnov siger, at aftalen kun hæver loftet. Den er ikke bevis for, at godset havde den værdi. Kunden får det faktiske tab op til det nye loft, altså 80.000 SDR. Uden angiven værdi var loftet kun 2.000 x 8,33 = 16.660 SDR.",
 p:"CMR §§ 29-30. Karnov-note 103."},
{k:"cmr", s:"En chauffør, der kører for en kontraherende fragtfører gennem en undertransportør, drak alkohol under kørslen og kørte i grøften. Godset blev totalskadet.",
 q:"Kan den kontraherende fragtfører bruge CMR-loftet?",
 o:["Nej, § 37 stk. 2 siger, at grov uagtsomhed hos nogen, han hæfter for efter § 4, fjerner loftet","Ja, han lavede ikke selv fejlen","Ja, fordi undertransportøren er ansvarlig","Kun halvdelen af loftet"],
 f:"CMR § 37 stk. 1 og 2 siger, at fragtføreren ikke kan bruge regler, der begrænser ansvaret, hvis han selv eller andre, han hæfter for efter § 4, har handlet med forsæt eller grov uagtsomhed i tjenesten. Karnov nævner beruselse som eksempel på grov uagtsomhed. Chaufføren hos undertransportøren er omfattet af § 4. Derfor er der gennembrud.",
 p:"CMR §§ 4 og 37. Karnov-note 114."},
{k:"cmr", s:"En trailer med cigaretter står på fragtførerens plads i en weekend. Chaufføren har fortalt nogle bekendte, hvad der er i traileren, og hvor den står. Traileren bliver stjålet.",
 q:"Er det grov uagtsomhed?",
 o:["Ja, Karnov nævner præcis denne sag (FED 1998 95) som grov uagtsomhed","Nej, pladsen var forsvarlig","Nej, cigaretter er ikke værdifulde","Kun hvis traileren var ulåst"],
 f:"Karnov-noten til CMR § 37 nævner FED 1998 95: Selv om det kunne være forsvarligt at stille traileren på pladsen, var bortkomsten forvoldt ved grov uagtsomhed, fordi chaufføren havde fortalt bekendte om godset og placeringen. Cigaretter er desuden typiske tyvevarer, som kræver særlig opmærksomhed.",
 p:"CMR § 37. Karnov-note 114."},
{k:"cmr", s:"Gods for 50.000 kr. bliver beskadiget på en CMR-transport. Godset er 40 procent mindre værd efter skaden. Det vejer 3.000 kg. (kurs 9,25)",
 q:"Hvad skal fragtføreren betale for skaden?",
 o:["20.000 kr. (40 procent af værdien), fordi det er under loftet","50.000 kr.","Ca. 231.000 kr. (loftet)","Intet, fordi godset ikke er tabt"],
 f:"CMR § 31 siger, at ved beskadigelse skal fragtføreren erstatte værdiforringelsen beregnet efter godsets værdi efter § 29. 40 procent af 50.000 kr. er 20.000 kr. Loftet er 3.000 x 8,33 x 9,25 = ca. 231.000 kr., så det begrænser ikke. Karnov nævner, at man ofte bruger en havarirapport til at fastsætte procentsatsen. Fragt og omkostninger erstattes forholdsmæssigt.",
 p:"CMR §§ 29 og 31. Karnov-note 104."},
{k:"cmr", s:"En modtager og chaufføren gennemgår godset sammen ved levering og skriver ned, at alt er i orden. 4 dage senere opdager modtageren en skjult skade og skriver straks til fragtføreren.",
 q:"Kan modtageren stadig gøre skaden gældende?",
 o:["Ja, hvis skaden ikke var synlig, og han reklamerer skriftligt inden 7 dage efter undersøgelsen (§ 38 stk. 2)","Nej, de har skrevet, at alt var i orden","Nej, fristen var 3 dage","Ja, uden nogen frist"],
 f:"CMR § 38 stk. 2 siger, at når modtager og fragtfører i fællesskab har undersøgt godset, kan der kun føres bevis mod resultatet, hvis skaden ikke var synlig, og modtageren skriftligt har gjort indsigelse inden 7 dage efter undersøgelsen, søn- og helligdage ikke medregnet. 4 dage er inden for fristen.",
 p:"CMR § 38 stk. 2."},
{k:"cmr", s:"En dansk kunde vil sagsøge en polsk fragtfører for en skade på en tur fra Polen til Danmark. Fragtføreren vil kun sagsøges i Polen.",
 q:"Kan kunden anlægge sagen i Danmark efter CMR?",
 o:["Ja, § 39 tillader sag, hvor godset skulle afleveres","Nej, kun i sagsøgtes land","Nej, kun ved voldgift","Kun hvis fragtføreren siger ja"],
 f:"CMR § 39 stk. 1 siger, at søgsmål kan anlægges i den stat, hvor sagsøgte har bopæl eller forretningssted, eller i den stat, hvor godset blev overtaget, eller hvor bestemmelsesstedet er. Bestemmelsesstedet er Danmark. Derfor kan kunden sagsøge i Danmark.",
 p:"CMR § 39."},
{k:"cmr", s:"En kunde sendte et skriftligt krav til fragtføreren 10 måneder efter afleveringen. Fragtføreren svarede først 4 måneder senere med et skriftligt afslag og sendte bilagene tilbage. Nu vil kunden anlægge sag.",
 q:"Er kravet forældet efter CMR § 41?",
 o:["Nej, det skriftlige krav standsede fristen, indtil fragtføreren skriftligt afviste det","Ja, der er gået over et år","Ja, fristen kan aldrig standses","Nej, CMR har ingen forældelse"],
 f:"CMR § 41 stk. 1 giver 1 års frist. Stk. 3 siger, at et skriftligt krav standser fristen, indtil fragtføreren skriftligt afviser kravet og sender dokumenterne tilbage. Der var gået 10 måneder, da kravet blev sendt. Fristen stod stille i 4 måneder. Derefter løber de sidste 2 måneder. Kunden skal skynde sig.",
 p:"CMR § 41 stk. 3. Karnov-note 137."},

// ===================== LUFT OG TOG =====================
{k:"luft", s:"Et flyselskab flyver elektronik fra København til Tokyo. En kasse bliver ødelagt, fordi afsenderen havde pakket den i en tynd plastpose uden polstring.",
 q:"Kan flyselskabet slippe?",
 o:["Ja, efter § 108 stk. 2 om mangelfuld emballering udført af andre end befordreren","Nej, luftfart har ingen fritagelser","Nej, fordi elektronik er værdifuldt","Ja, men kun halvdelen"],
 f:"Luftfartsloven § 108 stk. 2 nr. 2 fritager, i det omfang skaden skyldes mangelfuld emballering af godset udført af andre end befordreren og hans folk. Afsenderen pakkede kassen dårligt. Karnov siger, at skyldes skaden kun delvist en af grundene, nedsættes ansvaret tilsvarende.",
 p:"LFL § 108 stk. 2. Karnov-note 264."},
{k:"luft", s:"Et fly med blomster bliver forsinket 2 dage, fordi flyselskabet glemte at booke plads til sendingen. Blomsterne kan ikke sælges.",
 q:"Hvordan vurderes ansvaret?",
 o:["Efter § 109: flyselskabet hæfter, medmindre det beviser, at det tog alle rimelige forholdsregler, og det kan det ikke her","Det er objektivt ansvar uden undtagelser","Flyselskabet hæfter aldrig for forsinkelse","Kunden skal bevise flyselskabets skyld"],
 f:"Luftfartsloven § 109 siger, at befordreren hæfter for forsinkelse, hvis han ikke beviser, at han og hans folk tog alle forholdsregler, som med rimelighed kan kræves, for at undgå skaden. Det er culpa med omvendt bevisbyrde. At glemme at booke plads er ikke en rimelig forholdsregel. Flyselskabet hæfter, op til 26 SDR pr. kg.",
 p:"LFL §§ 109 og 111 stk. 5."},
{k:"luft", s:"En kasse på 20 kg ødelægges med fly. Kassen var en del af en sending på 100 kg på samme luftfragtbrev. De andre 80 kg er uskadte og har fuld værdi. (kurs 9,25)",
 q:"Hvilken vægt bruger man til loftet?",
 o:["Kun de 20 kg, der blev skadet: 20 x 26 SDR x 9,25 = ca. 4.810 kr.","Alle 100 kg","Ingen vægt, der er fast beløb","Halvdelen af 100 kg"],
 f:"Luftfartsloven § 111 stk. 5 siger, at går en del af godset tabt eller beskadiges, opgøres kun den samlede vægt af de berørte stykker gods. Kun hvis skaden forringer værdien af andre stykker på samme luftfragtbrev, medregnes deres vægt også. Her er de 80 kg uskadte. 20 x 26 = 520 SDR, ca. 4.810 kr.",
 p:"LFL § 111 stk. 5."},
{k:"luft", s:"En modtager får en kasse med fly. Han ser, at hjørnet er knust, men tager imod uden at sige noget. 20 dage senere skriver han til flyselskabet.",
 q:"Hvad er følgen?",
 o:["Kravet er bortfaldet, fordi skade skal meldes senest 14 dage efter modtagelsen (§§ 115-116)","Han har stadig 2 år","Han kan føre modbevis","Ingen følger"],
 f:"Luftfartsloven § 115 stk. 2 siger, at skade på gods skal meldes umiddelbart efter opdagelsen og senest 14 dage efter modtagelsen. § 116 siger, at gives meddelelsen ikke inden fristen, er ethvert krav mod befordreren bortfaldet, medmindre han har handlet svigagtigt. I luftfart er det altså ikke kun en bevisregel som i CMR og søloven ved skade.",
 p:"LFL §§ 115-116."},
{k:"luft", s:"En togsending med korn fra Tyskland til Danmark mister 0,8 procent af vægten undervejs, fordi korn naturligt tørrer lidt ud.",
 q:"Hæfter jernbanen for svindet efter CIM?",
 o:["Nej, ved tørt gods hæfter jernbanen kun for svind over 1 procent (art. 31)","Ja, for alt svind","Ja, 17 SDR pr. kg for svindet","Kun hvis kornet var dyrt"],
 f:"CIM art. 31 siger, at for gods, der naturligt svinder under transport, hæfter jernbanen kun for svind ud over 2 procent af vægten for flydende eller fugtigt gods og 1 procent for tørt gods. Korn er tørt gods, og 0,8 procent er under grænsen. Reglen gælder ikke, hvis det bevises, at tabet skyldes noget andet.",
 p:"CIM art. 31."},
{k:"luft", s:"En jernbane har ødelagt gods for 20.000 kr. Afsenderen havde i fragtbrevet skrevet en særlig interesse i levering på 50.000 kr. Det beviste tab inkl. følgetab er 45.000 kr.",
 q:"Hvad får afsenderen efter CIM?",
 o:["Op til 45.000 kr., fordi særlig interesse giver ret til ekstra bevist tab op til det angivne beløb","Kun 20.000 kr.","50.000 kr. uanset tab","17 SDR pr. kg"],
 f:"CIM art. 35 siger, at har afsenderen angivet en særlig interesse i levering, kan der kræves erstatning for yderligere bevist tab ud over art. 30, 32 og 33, op til det angivne beløb. Det beviste tab er 45.000 kr., som er under 50.000 kr. CMR § 33 og NSAB § 21 D har tilsvarende regler.",
 p:"CIM art. 35, CMR § 33, NSAB § 21 D."},

// ===================== KØBERET =====================
{k:"kob", s:"En dansk sælger sælger varer CIF Shanghai til en kinesisk køber. Sælger betaler fragt og forsikring. Skibet synker undervejs, og varerne går tabt.",
 q:"Hvem bærer risikoen, og hvem har kravet mod rederiet?",
 o:["Køberen, fordi risikoen ved CIF går over, når varen er om bord","Sælgeren, fordi han betalte fragten","Rederiet alene","Forsikringsselskabet bærer risikoen"],
 f:"CIF betyder Cost, Insurance and Freight. Sælger betaler fragt og forsikring til bestemmelseshavnen, men risikoen går over til køber, når varen er om bord i afskibningshavnen. Køberen har tabet og kan bruge den forsikring, sælger tegnede. Karnov nævner FED 2018 14 S, hvor en transportør ikke var ansvarlig over for en afsender ved CIF, fordi afsenderen ikke var den skadelidte.",
 p:"Incoterms 2020: CIF. Karnov-note 583 (FED 2018 14 S)."},
{k:"kob", s:"En dansk sælger sælger møbler FCA sælgers lager i Herning. Købers egen vognmand henter møblerne. Sælgers folk læsser dem på lastbilen. Under læsningen falder et skab ned og bliver ødelagt.",
 q:"Hvem bærer risikoen for skabet?",
 o:["Sælger, fordi levering ved FCA på sælgers sted først sker, når varen er læsset på købers transportmiddel","Køber, fordi hans vognmand var der","Vognmanden","Ingen"],
 f:"Ved FCA på sælgers eget sted skal sælger læsse varen på købers transportmiddel. Levering og risikoens overgang sker, når varen er læsset. Skabet faldt under læsningen, altså før levering. Derfor er det sælgers risiko. Incoterms-oversigten siger: 'Seller loads the goods only if pickup is at their premises.'",
 p:"Incoterms 2020: FCA."},
{k:"kob", s:"En sælger i Kolding sælger varer til en køber i Malmö. Ingen Incoterm, ingen lovvalgsaftale.",
 q:"Gælder CISG?",
 o:["Nej, Danmark og Sverige har taget nordisk forbehold (art. 94), så nordisk købelov gælder","Ja, altid mellem to lande","Ja, men kun del II","Nej, der gælder ingen regler"],
 f:"CISG art. 94 tillader lande med ens købelove at erklære, at CISG ikke gælder mellem dem. De nordiske lande har gjort det. Karnov siger, at CISG ikke gælder ved køb mellem parter i de nordiske lande. Så bruger man den nordiske købelov, som de internationale privatretlige regler peger på.",
 p:"CISG art. 94. Karnov-note til art. 1."},
{k:"kob", s:"En sælger leverer 3 delsendinger til samme køber. Sending 2 kommer 5 dage for sent. Det er et handelskøb. Der er ingen tegn på, at sending 3 også bliver forsinket.",
 q:"Kan køber hæve hele købet?",
 o:["Nej, ved successiv levering kan køber som udgangspunkt kun hæve for den forsinkede sending (KBL § 22)","Ja, enhver forsinkelse giver ret til at hæve alt","Nej, han kan slet ikke hæve","Ja, men kun efter CISG"],
 f:"KBL § 21 stk. 3 siger, at enhver forsinkelse er væsentlig i handelskøb. Men § 22 siger, at ved levering efterhånden kan køber kun hæve for den forsinkede levering. Han kan hæve for senere leveringer, hvis gentagelse må ventes, og hele købet, hvis det er begrundet i sammenhængen mellem leveringerne. Det var Furs & Feathers-situationen. CISG art. 73 har en lignende regel.",
 p:"KBL §§ 21-22, CISG art. 73."},
{k:"kob", s:"En køber i et handelskøb modtager en levering. Han ser tydeligt, at nogle varer er beskadiget, men siger først noget til sælger 3 uger senere.",
 q:"Hvad er problemet efter købeloven?",
 o:["I handelskøb skal køber reklamere straks over mangler, ellers kan han ikke gøre dem gældende (KBL § 52)","Ingen problemer, han har 2 år","Han skal reklamere til transportøren i stedet","Han mister kun retten til afslag"],
 f:"KBL § 51 siger, at køber i handelskøb skal undersøge varen, når den er leveret. § 52 siger, at viser der sig en mangel, skal køber give sælger meddelelse straks i handelskøb. Gør han ikke det, selv om han opdagede eller burde have opdaget manglen, kan han ikke senere gøre den gældende. 3 uger er ikke straks.",
 p:"KBL §§ 51-52."},
{k:"kob", s:"En sælger sælger varer DAP købers lager. Under transporten forsinkes godset en uge. Køber har ikke tabt penge, men vil hæve købet.",
 q:"Kan køber hæve købet efter købeloven, når det er et handelskøb?",
 o:["Ja, i handelskøb er enhver forsinkelse væsentlig (KBL § 21 stk. 3), og sælger bærer risikoen ved DAP","Nej, fordi transportøren er skyld i forsinkelsen","Nej, fordi køber ikke har tabt penge","Ja, men kun efter CISG"],
 f:"Ved DAP har sælger ikke leveret, før varen er hos køber. En uges forsinkelse er sælgers misligholdelse. KBL § 21 stk. 3 siger, at enhver forsinkelse er væsentlig i handelskøb, medmindre kun en ringe del er forsinket. Køber kan derfor hæve, også uden tab. Erstatning kræver derimod et tab. Sælger må selv tage det op med sin transportør.",
 p:"KBL § 21 stk. 3. Incoterms 2020: DAP."},
{k:"kob", s:"En sælger leverer 1.000 kasser vin. Der kommer kun 950. Køberen må gå ud fra, at det skulle være hele leverancen.",
 q:"Hvilken beføjelse har køber efter KBL § 50 i stedet for omlevering?",
 o:["Kræve de manglende 50 kasser efterleveret","Kræve alle 1.000 kasser omleveret","Ingen beføjelser","Kun hæve hele købet"],
 f:"KBL § 50 siger, at reglerne om mangler gælder, når den leverede mængde er for lille. Køber kan ikke kræve omlevering efter § 43, men kan i stedet kræve efterleveret, hvad der mangler. Han kan også kræve forholdsmæssigt afslag eller erstatning. Hæve kan han kun ved væsentlig mangel. 50 af 1.000 er næppe væsentligt.",
 p:"KBL §§ 43 og 50."},

// ===================== OPGAVER =====================
{k:"case", s:"Big Whale Shipping (BWS) er sælger af ost og har solgt den CFR Sines til Nyrup Mejeri. BWS har også booket rederiet MSC. Container 1 blev ødelagt om bord, fordi den ikke havde strøm.",
 q:"Hvem har kravet mod transportøren for den ødelagte ost?",
 o:["Nyrup Mejeri (køber), fordi risikoen gik over ved lastningen i Aarhus","BWS (sælger), fordi den bookede transporten","MSC","Ingen"],
 f:"Ved CFR går risikoen over, når osten er om bord i Aarhus. Skaden skete på skibet bagefter. Derfor er det køberen Nyrup Mejeri, der har tabet. CJ lagde i sin løsning vægt på, at begge skader skete i søtransportørens varetægt, og at NSAB § 2 sender sagen til søloven. Den ødelagte ost erstattes efter §§ 279-283.",
 p:"Incoterms 2020: CFR. SL §§ 274-275. CJ lektion 4."},
{k:"case", s:"I Helt i fisk kørte GT Transport medicinen til en temperaturkontrolleret terminal i Middelfart og læssede om. Her samlæssede GT med fisk. Big Whale Shipping vidste intet om det.",
 q:"Kan BWS undskylde sig med, at GT handlede bag deres ryg?",
 o:["Nej, efter CMR § 4 hæfter BWS for GT som for sine egne handlinger","Ja, BWS havde givet skriftlig instruks","Ja, fordi GT har opsagt samarbejdet","Nej, men kun hvis BWS vidste det"],
 f:"CMR § 4 siger, at fragtføreren er ansvarlig for handlinger og undladelser fra personer, han bruger til transporten, på samme måde som for sine egne. Karnov nævner, at det gælder også selvstændige medhjælpere som udførende fragtførere. At BWS gav instruks og opsagde GT bagefter, ændrer ikke ansvaret over for kunden. BWS kan tage regres hos GT, som er forsikret.",
 p:"CMR § 4. Karnov-note 13."},
{k:"case", s:"I Papaya kostede hele ordren 513.000 kr. CJ regnede tabet ud fra en detailpris på 51 kr. pr. kg for de 8.940 kg og en restværdi på 15 kr. pr. kg.",
 q:"Hvordan regnede CJ tabet på 348.660 kr.?",
 o:["8.940 kg x 51 kr. = 455.940 kr. minus restværdi 107.280 kr. (7.152 kg x 15 kr.)","513.000 kr. minus 15 procent","8.940 kg x 2 SDR x 9,25","Halvdelen af 513.000 kr."],
 f:"CJ's opgørelse: Oprindelig værdi 8.940 kg x 51 kr. = 455.940 kr. 20 procent (1.788 kg) var helt usælgeligt. De resterende 7.152 kg kunne sælges for 15 kr. = 107.280 kr. Tab: 455.940 - 107.280 = 348.660 kr. Bemærk at søloven § 279 egentlig regner værdien på udleveringsstedet. Det er derfor, CJ bruger prisen i Danmark.",
 p:"SL § 279. CJ's vejledende besvarelse."},
{k:"case", s:"I Furs & Feathers kom sending 2 fem dage for sent til Hamburg. Det vides ikke, om forsinkelsen skete i flyet eller på lastbilen.",
 q:"Hvad er loftet for forsinkelsen efter NSAB?",
 o:["Fragtbeløbet for opgaven (NSAB § 21 B)","8,33 SDR pr. kg","26 SDR pr. kg","Godsets værdi"],
 f:"Kan man ikke bevise, på hvilken transportform forsinkelsen skete, bruger man NSAB's egne regler. § 21 litra B siger, at speditørens ansvar for forsinkelse er begrænset til fragtbeløbet. Uden tidsløfte betales efter § 19 A kun direkte og rimelige omkostninger, som kunne forudses. Skete forsinkelsen i flyet, ville luftfartsloven § 109 og 26 SDR pr. kg gælde.",
 p:"NSAB §§ 19 og 21 B, LFL § 109."},
{k:"case", s:"I GPE-opgaven blev kammer 1 smidt over bord og kammer 2 skadet. Hvert kammer vejede 10.000 kg og var 200.000 kr. værd. Kurs ca. 9.",
 q:"Hvorfor var gennembrud næppe vigtigt for kammer 2?",
 o:["Fordi loftet på ca. 180.000 kr. (10.000 kg x 2 SDR) næsten dækker værdien, og reparationen var formentlig mindre","Fordi kammer 2 ikke blev skadet","Fordi søloven ikke har gennembrud","Fordi GPE ikke havde forsikring"],
 f:"Søloven § 280: 10.000 kg x 2 SDR = 20.000 SDR, ca. 180.000 kr. med kurs 9. Det er tæt på kammerets værdi på 200.000 kr. CJ skrev: 'Slår dette beløb til, behøver vi ikke foretage os yderligere.' Kun hvis skaden løber højere, er gennembrud relevant, og CJ mente ikke, at GPE kunne bevise grov uagtsomhed for kammer 2.",
 p:"SL §§ 280 og 283. CJ's GPE-bemærkninger."},
];
